#include <stdio.h>
#include <string.h>

#define MAX_WORDS 64
#define MAX_LEN 32
#define TOP 4

static char words[MAX_WORDS][MAX_LEN];
static int counts[MAX_WORDS];
static int total = 0;

static int find(const char *word) {
    for (int i = 0; i < total; i++) {
        if (strcmp(words[i], word) == 0) {
            return i;
        }
    }
    return -1;
}

static void add(const char *word) {
    int index = find(word);
    if (index >= 0) {
        counts[index] += 1;
        return;
    }
    if (total < MAX_WORDS) {
        strncpy(words[total], word, MAX_LEN - 1);
        words[total][MAX_LEN - 1] = '\0';
        counts[total] = 1;
        total += 1;
    }
}

static int best(void) {
    int index = 0;
    for (int i = 1; i < total; i++) {
        if (counts[i] > counts[index] ||
            (counts[i] == counts[index] && strcmp(words[i], words[index]) < 0)) {
            index = i;
        }
    }
    return index;
}

int main(void) {
    char text[] = "the quick brown fox jumps over the lazy dog the fox";
    for (char *word = strtok(text, " "); word != NULL; word = strtok(NULL, " ")) {
        add(word);
    }
    for (int printed = 0; printed < TOP && printed < total; printed++) {
        int index = best();
        if (counts[index] < 0) {
            break;
        }
        printf("%s: %d\n", words[index], counts[index]);
        counts[index] = -1;
    }
    return 0;
}

#include <stdio.h>

#define MAX_NODES 16

struct node {
    int value;
    int next;
};

static struct node pool[MAX_NODES];
static int used = 0;

static int push_front(int head, int value) {
    if (used >= MAX_NODES) {
        return head;
    }
    pool[used].value = value;
    pool[used].next = head;
    used += 1;
    return used - 1;
}

static int reverse(int head) {
    int previous = -1;
    int current = head;
    while (current != -1) {
        int next = pool[current].next;
        pool[current].next = previous;
        previous = current;
        current = next;
    }
    return previous;
}

static void render(int head) {
    int current = head;
    while (current != -1) {
        printf("%d", pool[current].value);
        current = pool[current].next;
        if (current != -1) {
            printf(" -> ");
        }
    }
    printf("\n");
}

int main(void) {
    int values[] = {1, 2, 3, 4, 5};
    int count = (int)(sizeof(values) / sizeof(values[0]));
    int head = -1;
    for (int i = count - 1; i >= 0; i--) {
        head = push_front(head, values[i]);
    }
    render(head);
    render(reverse(head));
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define COUNT 3

struct record {
    char name[12];
    int qty;
    double price;
};

static double value(const struct record *entry) {
    return entry->qty * entry->price;
}

static int by_value(const void *left, const void *right) {
    const struct record *a = (const struct record *)left;
    const struct record *b = (const struct record *)right;
    double va = value(a);
    double vb = value(b);
    if (va > vb) {
        return -1;
    }
    if (va < vb) {
        return 1;
    }
    return strcmp(a->name, b->name);
}

static int by_name(const void *left, const void *right) {
    const struct record *a = (const struct record *)left;
    const struct record *b = (const struct record *)right;
    return strcmp(a->name, b->name);
}

static void render(const struct record *rows, int count) {
    for (int i = 0; i < count; i++) {
        if (i > 0) {
            printf(", ");
        }
        printf("%s(%d)", rows[i].name, rows[i].qty);
    }
    printf("\n");
}

int main(void) {
    struct record rows[COUNT] = {
    {"hammer", 3, 12.00},
    {"saw", 0, 18.50},
    {"drill", 2, 45.00},
    };
    struct record copy[COUNT];
    memcpy(copy, rows, sizeof(rows));
    qsort(copy, COUNT, sizeof(struct record), by_value);
    printf("value ");
    render(copy, COUNT);
    memcpy(copy, rows, sizeof(rows));
    qsort(copy, COUNT, sizeof(struct record), by_name);
    printf("name  ");
    render(copy, COUNT);
    return 0;
}

package main

import (
	"fmt"
	"sort"
)

type record struct {
	name  string
	qty   int
	price float64
}

func byValue(rows []record) []record {
	out := append([]record{}, rows...)
	sort.Slice(out, func(i, j int) bool {
		left := float64(out[i].qty) * out[i].price
		right := float64(out[j].qty) * out[j].price
		if left != right {
			return left > right
		}
		return out[i].name < out[j].name
	})
	return out
}

func byName(rows []record) []record {
	out := append([]record{}, rows...)
	sort.Slice(out, func(i, j int) bool { return out[i].name < out[j].name })
	return out
}

func render(rows []record) string {
	out := ""
	for index, entry := range rows {
		if index > 0 {
			out += ", "
		}
		out += fmt.Sprintf("%s(%d)", entry.name, entry.qty)
	}
	return out
}

func main() {
	rows := []record{
		{"hammer", 3, 12.00},
		{"saw", 0, 18.50},
		{"drill", 2, 45.00},
	}
	fmt.Println("value", render(byValue(rows)))
	fmt.Println("name ", render(byName(rows)))
}

