	for _, word := range items {
		out = append(out, capitalise(word))
	}
	return out
}

func longest(items []string) string {
	best := ""
	for _, word := range items {
		if len(word) > len(best) {
			best = word
		}
	}
	return best
}

func totalLetters(items []string) int {
	sum := 0
	for _, word := range items {
		sum += len(word)
	}
	return sum
}

