REQUEST: A Go program in two files in package main: one defines an Employee struct with Name and Salary and a ByName sort type, the other has main() that sorts a hardcoded slice and prints each employee's name and salary.
LANGUAGE: go
TARGET FILE: main.go

### Existing project files
--- employee.go ---
package main

import (
	"fmt"
	"sort"
)

type Employee struct {
	ID         int
	Name       string
	Department string
	Salary     int
}

func SortBySalary(employees []Employee) []Employee {
	sorted := make([]Employee, len(employees))
	copy(sorted, employees)
	sort.Slice(sorted, func(i, j int) bool {
		return sorted[i].Salary < sorted[j].Salary
	})
	return sorted
}

func SortByName(employees []Employee) []Employee {
	sorted := make([]Employee, len(employees))
	copy(sorted, employees)
	sort.Slice(sorted, func(i, j int) bool {
		return sorted[i].Name < sorted[j].Name
	})
	return sorted
}

func PrintEmployees(employees []Employee) {
	for _, e := range employees {
		fmt.Printf("ID: %d, Name: %s, Dept: %s, Salary: %d\n", e.ID, e.Name, e.Department, e.Salary)
	}
}

